import{_ as e,o as n,c as i,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 07 — Subscription & Billing (UC-122 – UC-127)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/07-subscription.md","filePath":"ba/use-cases/07-subscription.md"}'),o={name:"ba/use-cases/07-subscription.md"};function a(l,t,s,d,r,g){return n(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="uc-07-—-subscription-billing-uc-122-–-uc-127" tabindex="-1">UC 07 — Subscription &amp; Billing (<code>UC-122</code> – <code>UC-127</code>) <a class="header-anchor" href="#uc-07-—-subscription-billing-uc-122-–-uc-127" aria-label="Permalink to &quot;UC 07 — Subscription &amp; Billing (`UC-122` – `UC-127`)&quot;">​</a></h1><p>&gt; <a href="./06-publishing-social.html">&lt;&lt; 06-publishing-social.md</a> | <a href="./README.html">UC Index</a> | <a href="./../08-subscription-billing.html">Domain BA Spec: 08-subscription-billing.md</a> | <a href="./08-admin-functions.html">08-admin-functions.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-6-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (6 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-6-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (6 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-122</code></td><td style="text-align:left;">Upgrade Plan</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.9.1</code></td><td style="text-align:left;"><code>BR-15, BR-58, BR-59</code></td></tr><tr><td style="text-align:center;"><code>UC-123</code></td><td style="text-align:left;">Make Payment (SePay)</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.9.2</code></td><td style="text-align:left;"><code>BR-15, BR-58, BR-59, BR-60, BR-61</code></td></tr><tr><td style="text-align:center;"><code>UC-124</code></td><td style="text-align:left;">View Invoice History</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.9.3</code></td><td style="text-align:left;"><code>BR-15, BR-61</code></td></tr><tr><td style="text-align:center;"><code>UC-125</code></td><td style="text-align:left;">View AI Credit Tracking</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.9.4</code></td><td style="text-align:left;"><code>BR-48, BR-60, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-126</code></td><td style="text-align:left;">Buy Credit</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.9.5</code></td><td style="text-align:left;"><code>BR-15, BR-59, BR-60</code></td></tr><tr><td style="text-align:center;"><code>UC-127</code></td><td style="text-align:left;">Set Credit</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.9.6</code></td><td style="text-align:left;"><code>BR-15, BR-48, BR-60, BR-64</code></td></tr></tbody></table><hr><h2 id="uc-122-—-upgrade-plan" tabindex="-1">UC-122 — Upgrade Plan <a class="header-anchor" href="#uc-122-—-upgrade-plan" aria-label="Permalink to &quot;UC-122 — Upgrade Plan&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.1</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-58, BR-59</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG36, MSG55</code></li><li><strong>Specification &amp; Flow:</strong> Nâng cấp gói đăng ký dịch vụ của Agency từ gói mặc định (Basic/Free) lên gói cao hơn (PLUS hoặc Enterprise) trên màn hình Subscription Plans (/subscription/plans). Hệ thống chỉ hỗ trợ nâng cấp lên gói có cấp bậc cao hơn (đã lược bỏ luồng hạ cấp gói trực tiếp) để mở rộng giới hạn số lượng Workspace, số lượng thành viên, số kênh mạng xã hội kết nối và định mức AI Credit hàng tháng (BR-58).</li></ul><hr><h2 id="uc-123-—-make-payment-sepay" tabindex="-1">UC-123 — Make Payment (SePay) <a class="header-anchor" href="#uc-123-—-make-payment-sepay" aria-label="Permalink to &quot;UC-123 — Make Payment (SePay)&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.2</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-58, BR-59, BR-60, BR-61</code></li><li><strong>System Messages:</strong> <code>MSG07, MSG36, MSG56</code></li><li><strong>Specification &amp; Flow:</strong> Thực hiện thanh toán đơn hàng nâng cấp gói cước hoặc mua thêm AI Credit thông qua cổng thanh toán VietQR SePay (Make Payment SePay — /billing/checkout/:transactionId). Hệ thống khởi tạo giao dịch ở trạng thái PENDING tuân thủ nghiêm ngặt tính chất ACID trong PostgreSQL, sinh mã QR chuyển khoản ngân hàng chứa mã tham chiếu duy nhất; khi nhận Webhook xác thực chữ ký hợp lệ từ SePay, hệ thống xử lý bất biến (idempotent) để chuyển giao dịch sang PAID và kích hoạt ngay quyền lợi gói/credit (BR-59).</li></ul><hr><h2 id="uc-124-—-view-invoice-history" tabindex="-1">UC-124 — View Invoice History <a class="header-anchor" href="#uc-124-—-view-invoice-history" aria-label="Permalink to &quot;UC-124 — View Invoice History&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.3</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-61</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem lịch sử toàn bộ các giao dịch thanh toán và tải xuống hóa đơn điện tử dạng PDF của tài khoản/Agency (View Invoice History — /billing/invoices). Hiển thị Mã hóa đơn, Loại giao dịch (Nâng cấp gói / Mua thêm AI Credit), Số tiền, Phương thức thanh toán (SePay VietQR), Trạng thái (PAID, PENDING, EXPIRED, FAILED), Thời gian giao dịch và nút tải tệp hóa đơn PDF (BR-61).</li></ul><hr><h2 id="uc-125-—-view-ai-credit-tracking" tabindex="-1">UC-125 — View AI Credit Tracking <a class="header-anchor" href="#uc-125-—-view-ai-credit-tracking" aria-label="Permalink to &quot;UC-125 — View AI Credit Tracking&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.4</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-48, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Giám sát chi tiết lượng AI Credit đã tiêu thụ và số dư còn lại theo thời gian thực (View AI Credit Tracking — /billing/credits). Thống kê lượng credit mà các Creator đã sử dụng theo từng loại tác vụ AI (Generate Caption, Image, Video, Virtual Ambassador), theo từng Workspace và theo kỳ thanh toán tháng (lượng credit định kỳ hàng tháng không cộng dồn sang tháng sau, BR-48, BR-60).</li></ul><hr><h2 id="uc-126-—-buy-credit" tabindex="-1">UC-126 — Buy Credit <a class="header-anchor" href="#uc-126-—-buy-credit" aria-label="Permalink to &quot;UC-126 — Buy Credit&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.5</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-59, BR-60</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36, MSG55</code></li><li><strong>Specification &amp; Flow:</strong> Mua bổ sung các gói nạp thêm AI Credit (Top-up Credit Packs) khi Agency sử dụng hết định mức credit có sẵn trong gói PLUS/Enterprise (Buy Credit — /billing/credits/buy). Khởi tạo giao dịch thanh toán qua SePay (3.9.2) và cộng ngay số lượng AI Credit mua thêm vào tổng quỹ khả dụng của Agency sau khi thanh toán thành công (BR-59, BR-60).</li></ul><hr><h2 id="uc-127-—-set-credit" tabindex="-1">UC-127 — Set Credit <a class="header-anchor" href="#uc-127-—-set-credit" aria-label="Permalink to &quot;UC-127 — Set Credit&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.9.6</code> (3.9 Subscription &amp; Billing)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-48, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG03, MSG07, MSG57</code></li><li><strong>Specification &amp; Flow:</strong> Thiết lập và điều chỉnh hạn mức tiêu thụ AI Credit tối đa hàng tháng cho từng Workspace trực thuộc Agency (Set Credit — /agency/:id/workspaces/:id/credit-limit). Giúp Owner kiểm soát phân bổ ngân sách AI giữa các dự án/nhãn hàng; tổng hạn mức cấp cho các Workspace không vượt quá quỹ credit của Agency và không thấp hơn số credit mà Workspace đó đã tiêu thụ trong kỳ hiện tại (BR-60).</li></ul>',23)])])}const p=e(o,[["render",a]]);export{u as __pageData,p as default};
